import {accountTableHTML,mountAccountTable} from './admin-accounts.mjs';
import {mountDashboard,icon} from './dashboard.mjs';
import {createAdminService} from './admin-service.mjs';
import {escapeHTML as esc} from './transfer-ui.mjs';
import {FUNDING_ASSETS,networkLabel,toUnits,fromUnits,normalizeTransaction,validateAddress,TOKEN_CONTRACTS} from './funding-catalog.mjs';
const decimal=v=>String(v??'0').replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,'');
export function adminHTML({preview=false}={}){return '<div class="finance-page"><div class="finance-heading"><div><p class="eyebrow">AUREXMARKETS OPERATIONS</p><h1>Finance Admin</h1><p>Review deposits, process withdrawals and manage account balances.</p></div><span class="finance-badge">'+(preview?'Read-only preview':'Restricted access')+'</span></div><p id="admin-feedback" role="status" class="transfer-caption">'+(preview?'Sign in with an administrator account to view and manage real requests.':'Checking administrator access…')+'</p><div id="admin-workspace" '+(preview?'':'hidden')+'><div id="admin-account-table">'+accountTableHTML()+'</div><div class="finance-toolbar"><form id="admin-search-form"><label for="admin-account-search">Find an account</label><div><input id="admin-account-search" placeholder="Search email or name" maxlength="254"><button class="secondary-button" type="submit">Search</button></div></form><label>Account<select id="admin-account"><option value="">All accounts</option></select></label><label>Requests<select id="admin-kind"><option value="all">All types</option><option value="deposit">Deposits</option><option value="withdrawal">Withdrawals</option></select></label><label>Status<select id="admin-filter"><option value="queue">Review queue</option><option value="all">All statuses</option><option value="completed">Confirmed / paid</option><option value="closed">Rejected / cancelled</option></select></label><button id="admin-refresh" class="secondary-button">Refresh</button></div><div class="finance-layout"><section class="deposit-panel finance-requests"><div class="finance-section-heading"><h2>Transaction requests</h2><span id="admin-page-label">Page 1</span></div><p class="transfer-caption">Verify on-chain activity and account ownership before crediting a deposit. Start processing a withdrawal before sending it from your wallet.</p><div id="admin-requests"><p class="transfer-caption">No requests to display.</p></div><div class="transfer-actions"><button id="admin-previous" class="transfer-back" disabled>← Previous</button><button id="admin-next" class="transfer-back" disabled>Next →</button></div></section><aside><section class="deposit-panel"><h2>Account balances</h2><p class="transfer-caption">Select an account to inspect available and reserved funds. Amounts are in each asset’s native units.</p><div id="admin-balances"></div></section><section class="deposit-panel finance-adjust"><h2>Balance adjustment</h2><p class="transfer-caption">Use deposit approval for received funds. Adjustments are for documented corrections and never change reserved withdrawals.</p><form id="admin-adjust-form"><label for="admin-adjust-asset">Asset</label><select id="admin-adjust-asset">'+Object.entries(FUNDING_ASSETS).map(([s,a])=>'<option value="'+s+'">'+s+' · '+a.name+'</option>').join('')+'</select><label for="admin-adjust-direction">Change</label><select id="admin-adjust-direction"><option value="credit">Add to available balance</option><option value="debit">Subtract from available balance</option></select><label for="admin-adjust-amount">Amount</label><input id="admin-adjust-amount" inputmode="decimal" required><label for="admin-adjust-note">Reason / supporting reference</label><textarea id="admin-adjust-note" minlength="5" maxlength="2000" required></textarea><label class="funding-consent"><input type="checkbox" required> I checked the selected account, asset and correction.</label><button type="submit" class="deposit-continue">Apply Adjustment</button></form></section></aside></div><section class="deposit-panel finance-audit"><h2>Wallet audit trail</h2><p class="transfer-caption">Latest 50 ledger entries for the selected account filter.</p><div id="admin-ledger"></div></section><section class="deposit-panel finance-audit"><h2>Administrator activity</h2><p class="transfer-caption">Latest 30 recorded admin actions.</p><div id="admin-commands"></div></section></div><dialog id="finance-review-dialog" class="finance-dialog"><form id="admin-review-form"><div class="finance-section-heading"><h2 id="admin-review-title">Review request</h2><button id="admin-review-close" type="button" class="transfer-back" aria-label="Close review">×</button></div><div id="admin-review-details"></div><div id="admin-review-fields"></div><label for="admin-review-note">Review evidence / reason</label><textarea id="admin-review-note" minlength="5" maxlength="2000" required></textarea><label class="funding-consent"><input id="admin-review-consent" type="checkbox" required><span id="admin-review-consent-text"></span></label><p id="admin-review-error" role="alert" class="deposit-error"></p><button id="admin-review-submit" class="deposit-continue" type="submit">Confirm</button></form></dialog></div>';}
export function requestDetails(row,account){const token=TOKEN_CONTRACTS[row.asset]?.[row.network];return '<p><strong>'+esc(row.asset)+' · '+esc(networkLabel(row.asset,row.network))+'</strong> · '+esc(row.kind==='withdrawal'?'Withdrawal':row.kind==='simulation'?'Legacy hold':'Deposit')+'</p><dl class="finance-facts"><dt>Account</dt><dd>'+esc(account||row.user_id)+'</dd><dt>Request ID</dt><dd>'+esc(row.id)+'</dd><dt>Amount</dt><dd>'+esc(decimal(row.amount))+' '+esc(row.asset)+'</dd><dt>Status</dt><dd>'+esc(row.status.replaceAll('_',' '))+'</dd><dt>'+(row.kind==='withdrawal'?'Payout destination':'Receiving address')+'</dt><dd><code>'+esc(row.address||'Not supplied')+'</code></dd>'+(row.memo?'<dt>Memo / tag</dt><dd>'+esc(row.memo)+'</dd>':'')+(token?'<dt>Expected token</dt><dd>'+esc(token.label)+'<br><code>'+esc(token.address)+'</code></dd>':'')+(row.transaction_hash?'<dt>Deposit transaction</dt><dd><code>'+esc(row.transaction_hash)+'</code> · transfer index '+row.transfer_index+'</dd>':'')+(row.payout_hash?'<dt>Payout transaction</dt><dd><code>'+esc(row.payout_hash)+'</code></dd>':'')+(row.review_note?'<dt>Review note</dt><dd>'+esc(row.review_note)+'</dd>':'')+'</dl>';}
export function mountAdmin(root,options={}){mountDashboard(root,{...options,view:'admin',mainHTML:adminHTML(options)});const page=root.querySelector('.finance-page'),feedback=page.querySelector('#admin-feedback'),workspace=page.querySelector('#admin-workspace'),dialog=page.querySelector('#finance-review-dialog');let service=null,accounts=[],data={requests:[],balances:[],ledger:[],commands:[]},pageNo=0,busy=false,loadId=0,review=null,adjustId=crypto.randomUUID();const q=s=>page.querySelector(s);const accountName=id=>accounts.find(a=>a.id===id)?.email||id;
 function optionsList(selected=''){q('#admin-account').innerHTML='<option value="">All accounts</option>'+accounts.map(a=>'<option value="'+a.id+'">'+esc(a.email||a.id)+' · '+esc([a.first_name,a.last_name].filter(Boolean).join(' '))+'</option>').join('');q('#admin-account').value=selected;}
 function render(){q('#admin-page-label').textContent='Page '+(pageNo+1)+' · '+data.requests.length+' requests';q('#admin-previous').disabled=pageNo===0;q('#admin-next').disabled=data.requests.length<50;q('#admin-requests').innerHTML=data.requests.length?data.requests.map(r=>'<article class="finance-request"><div class="finance-section-heading"><strong>'+esc(decimal(r.amount))+' '+r.asset+'</strong><span class="funding-status">'+esc(r.status.replaceAll('_',' '))+'</span></div>'+requestDetails(r,accountName(r.user_id))+'<div class="transfer-actions">'+(r.kind==='deposit'&&r.status==='pending_review'?'<button class="deposit-continue" data-admin-action="approve_deposit" data-request="'+r.id+'">Approve & Credit</button><button class="transfer-back" data-admin-action="reject_deposit" data-request="'+r.id+'">Reject Deposit</button>':'')+(r.kind==='withdrawal'&&r.status==='pending_review'?'<button class="deposit-continue" data-admin-action="start_withdrawal" data-request="'+r.id+'">Start Processing</button><button class="transfer-back" data-admin-action="reject_withdrawal" data-request="'+r.id+'">Reject & Release</button>':'')+(r.kind==='withdrawal'&&r.status==='processing'?'<button class="deposit-continue" data-admin-action="pay_withdrawal" data-request="'+r.id+'">Record Payment</button><button class="transfer-back" data-admin-action="reject_withdrawal" data-request="'+r.id+'">Reject & Release</button>':'')+'</div></article>').join(''):'<p class="transfer-caption">No requests match this filter.</p>';q('#admin-balances').innerHTML=data.balances.length?data.balances.map(b=>'<div class="finance-wallet"><small>'+esc(accountName(b.user_id))+'</small><strong>'+b.asset+'</strong><p>'+esc(decimal(b.available))+' available<br>'+esc(decimal(b.reserved))+' reserved</p></div>').join(''):'<p class="transfer-caption">No credited balances.</p>';q('#admin-ledger').innerHTML=data.ledger.length?data.ledger.map(e=>'<article class="finance-audit-row"><strong>'+esc(e.action.replaceAll('_',' '))+' · '+e.asset+'</strong><p>'+esc(accountName(e.user_id))+'</p><p>Available '+esc(decimal(e.available_delta))+' · Reserved '+esc(decimal(e.reserved_delta))+'</p><small>'+esc(new Date(e.created_at).toLocaleString())+' · '+esc(e.request_id||e.command_id)+'</small></article>').join(''):'<p class="transfer-caption">No ledger entries.</p>';q('#admin-commands').innerHTML=data.commands.length?data.commands.map(c=>'<article class="finance-audit-row"><strong>'+esc(c.action.replaceAll('_',' '))+' · '+esc(c.result_status)+'</strong><p>'+esc(c.note)+'</p><small>Admin '+esc(accountName(c.actor_id))+' · '+esc(new Date(c.created_at).toLocaleString())+'</small></article>').join(''):'<p class="transfer-caption">No admin actions.</p>';}
 async function refresh(){if(!service)return;const token=++loadId;feedback.textContent='Refreshing requests…';try{const loaded=await service.load({filter:q('#admin-filter').value,page:pageNo,accountId:q('#admin-account').value,kind:q('#admin-kind').value});if(!page.isConnected||token!==loadId)return;data=loaded;render();feedback.textContent='Updated '+new Date().toLocaleTimeString()+'. Changes are recorded in the audit trail.';}catch(e){feedback.textContent=e.message;}}
 function openReview(action,row){review={action,row,id:crypto.randomUUID()};q('#admin-review-form').reset();q('#admin-review-error').textContent='';q('#admin-review-title').textContent={approve_deposit:'Approve deposit & credit balance',reject_deposit:'Reject deposit',start_withdrawal:'Start withdrawal processing',pay_withdrawal:'Record completed payout',reject_withdrawal:'Reject withdrawal & release balance'}[action];q('#admin-review-details').innerHTML=requestDetails(row,accountName(row.user_id));q('#admin-review-fields').innerHTML=action==='approve_deposit'?'<label for="admin-verified-amount">Actual amount verified on-chain ('+row.asset+')</label><input id="admin-verified-amount" inputmode="decimal" value="'+esc(decimal(row.amount))+'" required>':action==='pay_withdrawal'?'<label for="admin-payout-hash">Payout transaction hash</label><input id="admin-payout-hash" autocomplete="off" required><label for="admin-network-fee">Actual sending-wallet network fee ('+(row.network==='bsc'?'BNB':row.network==='ethereum'?'ETH':row.network==='tron'?'TRX':row.asset)+')</label><input id="admin-network-fee" inputmode="decimal" required placeholder="Enter the actual network fee">':'';q('#admin-review-consent-text').textContent=action==='approve_deposit'?'I verified settlement, amount, asset/token contract, receiving address, network and depositor ownership.':action==='pay_withdrawal'?'I already sent the requested amount to the recorded destination and verified this payout transaction.':action==='reject_withdrawal'?'No funds were sent for this request. Releasing the reserved balance is correct.':action==='start_withdrawal'?'I will process this request from my wallet. The user cannot cancel once processing starts.':'I verified the reason for rejecting this deposit. No balance will be credited.';dialog.showModal();}
 q('#admin-review-close').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
 page.addEventListener('click',e=>{const b=e.target.closest('[data-admin-action]');if(b&&service&&!busy){const row=data.requests.find(r=>r.id===b.dataset.request);if(row)openReview(b.dataset.adminAction,row);}});
 q('#admin-review-form').onsubmit=async e=>{e.preventDefault();if(busy||!service||!review)return;busy=true;q('#admin-review-submit').disabled=true;q('#admin-review-error').textContent='';try{const {action,row,id}=review,values={request_id:row.id,note:q('#admin-review-note').value};if(action==='approve_deposit')values.amount=fromUnits(toUnits(q('#admin-verified-amount').value,row.asset),row.asset);if(action==='start_withdrawal'||action==='pay_withdrawal')validateAddress(row.network,row.address);if(action==='pay_withdrawal'){values.payout_hash=normalizeTransaction(row.network,q('#admin-payout-hash').value);const gasAsset=row.network==='bsc'?'BNB':row.network==='ethereum'?'ETH':row.network==='tron'?'TRX':row.asset;values.network_fee=fromUnits(toUnits(q('#admin-network-fee').value,gasAsset,{allowZero:true}),gasAsset);}await service.execute(action,values,id);dialog.close();await refresh();}catch(e){q('#admin-review-error').textContent=e.message;}finally{busy=false;q('#admin-review-submit').disabled=false;}};
 q('#admin-adjust-form').onsubmit=async e=>{e.preventDefault();if(busy||!service)return;const button=e.target.querySelector('button');busy=true;button.disabled=true;try{const account_id=q('#admin-account').value;if(!account_id)throw Error('Select the account to adjust before submitting.');const asset=q('#admin-adjust-asset').value,amount=fromUnits(toUnits(q('#admin-adjust-amount').value,asset),asset);await service.execute('adjust_balance',{account_id,asset,amount:(q('#admin-adjust-direction').value==='debit'?'-':'')+amount,note:q('#admin-adjust-note').value},adjustId);adjustId=crypto.randomUUID();e.target.reset();await refresh();}catch(e){feedback.textContent=e.message;}finally{busy=false;button.disabled=false;}};
 q('#admin-search-form').onsubmit=async e=>{e.preventDefault();if(!service)return;try{accounts=await service.directory(q('#admin-account-search').value.trim());optionsList();pageNo=0;await refresh();}catch(e){feedback.textContent=e.message;}};for(const selector of ['#admin-account','#admin-kind','#admin-filter'])q(selector).onchange=()=>{pageNo=0;if(selector==='#admin-account'){q('#admin-adjust-form').reset();adjustId=crypto.randomUUID();}refresh();};q('#admin-adjust-form').addEventListener('input',e=>{if(e.target.type!=='checkbox')q('#admin-adjust-form input[type=checkbox]').checked=false;});q('#admin-refresh').onclick=refresh;q('#admin-previous').onclick=()=>{if(pageNo>0){pageNo--;refresh();}};q('#admin-next').onclick=()=>{pageNo++;refresh();};
 if(options.preview){mountAccountTable(q('#admin-account-table'),null);workspace.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=true);return;}
 Promise.resolve(options.getAccounts?.()).then(async accountService=>{if(!accountService)return;service=createAdminService(accountService);if(!await service.isAdmin())throw Error('Access restricted. Sign in with your finance administrator account.');accounts=await service.directory();if(!page.isConnected)return;optionsList();workspace.hidden=false;mountAccountTable(q('#admin-account-table'),service,refresh);await refresh();}).catch(e=>{feedback.textContent=e.message;workspace.hidden=true;});
}
